  Lemma dll_at_spec : forall l k x, (k < length l)%nat ->
    dll_at l k x <->
    exists mt, a_meta A x = Some mt /\
      mt_next mt = (if (S k <? length l)%nat then nth (S k) l 0 else nth 0 l 0) /\
      mt_prev mt = (if (0 <? k)%nat then nth (k - 1) l 0 else nth (length l - 1) l 0).
